"""Deepavali 2026: invite hotel & homestay owners to list on Hill Booker (5% commission offer).
Run on the server:  docker compose -f docker-compose.prod.yml exec -T api python - < tools/diwali_owner_emails_2.py
Sends one email per owner (plain text + the offer poster as a JPG attachment) from the site's SMTP mailbox,
20 seconds apart, then a summary and a copy to info@hillbooker.com. Each line of output says SENT or FAILED."""
import base64, smtplib, sys, time
from email.message import EmailMessage
sys.path.insert(0, "/srv")
from app.config import settings

OWNERS = [["Chikmagalur", "The Coffee Bean Homestay", "a.a.nishchit@gmail.com"], ["Chikmagalur", "The Jungle Valley Homestay", "junglevaleyhomestay@gmail.com"], ["Chikmagalur", "Green Park Homestay Mudigere", "stayatchikmaglur@gmail.com"], ["Chikmagalur", "Girikallu Homestay", "girikalluhomestay@gmail.com"], ["Chikmagalur", "Megur Homestay", "megurhomestay@gmail.com"], ["Vagamon", "V Homes Vagamon", "vhomesvagamon@gmail.com"], ["Vagamon", "Drizzleinn Homestay", "robinsparadisevagamon@gmail.com"], ["Vagamon", "Lael Koodarathil Homestay", "lijolinilael@gmail.com"], ["Vagamon", "Spathodea Homestay", "spathodeahomestay@gmail.com"], ["Vagamon", "Fainex Luxe Aer", "fainexluxeaer@gmail.com"], ["Yercaud", "JJ Homestay and Cottages", "jjhomestaycottage@gmail.com"], ["Yercaud", "Oyla Cottages", "oylayercaud@gmail.com"], ["Yercaud", "Yercaud Chill Stay", "yercaudchillstay@gmail.com"], ["Yercaud", "Yercaud Cottage", "yercaudcottage@gmail.com"], ["Yercaud", "Coco Resort Yercaud", "nehrukarthi9@gmail.com"], ["Thekkady", "Kerala Spices Homestay", "keralaspiceshomestay@gmail.com"], ["Thekkady", "Periyar Villa Home Stay", "periyarvilla@gmail.com"], ["Thekkady", "Misty Green Homestay", "mistygreenstay@gmail.com"], ["Thekkady", "Ferndale Homestay", "ferndalehomestay@gmail.com"], ["Thekkady", "Oriole Homestay", "oriolehomestay@gmail.com"]]
SUBJECT = "Happy Deepavali from Hill Booker – list {property} at just 5% commission"
BODY = "Hello {property} team,\n\nWishing you and your family a very Happy Deepavali! May this festival of lights bring you full rooms and happy guests all season.\n\nI'm writing from Hill Booker (hillbooker.com), a booking website for hill-station and backwater stays in South India: Munnar, Ooty, Kodaikanal, Valparai, Alleppey, Coorg, Wayanad and more. We came across {property} in {city} and would love to have you with us.\n\nOUR DEEPAVALI OFFER FOR NEW PARTNERS\n- List your property on Hill Booker by 30 November 2026\n- Pay only 5% commission (our normal rate is 8%) on every booking until 28 February 2027\n- Listing is free: no joining fee, no monthly charges\n\nHOW IT WORKS\n- You add your rooms, photos and prices yourself, and open only the dates you want to sell\n- Guests pay a 30% advance online when they book and pay the rest to you at check-in\n- Instant WhatsApp notification the moment a booking is made, with the guest's name, check-in date and room, plus the invoice\n- A WhatsApp message if a guest cancels\n- Your share of the advance is paid to your UPI ID or bank account after the guest checks in\n\nList your property here (takes about 10 minutes): https://hillbooker.com/register\n\nOur Deepavali offer poster is attached.\n\nQuestions? Call or WhatsApp us on +91 83008 41442 or +91 93457 77130, or simply reply to this email.\n\nWarm Deepavali wishes,\nMurugan\nHill Booker\nhttps://hillbooker.com | +91 83008 41442 | +91 93457 77130\n\nIf you'd rather not hear from us, just reply \"no thanks\" and we won't email you again.\n"
POSTER = base64.b64decode("")


def send(to, subject, body):
    msg = EmailMessage()
    msg["Subject"], msg["To"], msg["From"] = subject, to, settings.smtp_from
    msg["Reply-To"] = "info@hillbooker.com"
    msg.set_content(body)
    msg.add_attachment(POSTER, maintype="image", subtype="jpeg", filename="Hill-Booker-Deepavali-offer.jpg")
    try:
        if settings.smtp_security == "ssl":
            server = smtplib.SMTP_SSL(settings.smtp_host, settings.smtp_port, timeout=30)
        else:
            server = smtplib.SMTP(settings.smtp_host, settings.smtp_port, timeout=30)
            if settings.smtp_security == "starttls":
                server.starttls()
        with server:
            if settings.smtp_user:
                server.login(settings.smtp_user, settings.smtp_password)
            server.send_message(msg)
        return True
    except Exception as e:
        print("   error:", e, flush=True)
        return False


if not (settings.smtp_host and settings.smtp_from):
    print("Email is not set up on the server (SMTP_HOST / SMTP_FROM empty). Nothing sent.")
    sys.exit(1)

sent = failed = 0
bad = []
for i, (city, prop, email) in enumerate(OWNERS, 1):
    ok = send(email, SUBJECT.format(property=prop, city=city), BODY.format(property=prop, city=city))
    print(f"{i:>2}/{len(OWNERS)} {'SENT  ' if ok else 'FAILED'} {email}  ({prop}, {city})", flush=True)
    if ok:
        sent += 1
    else:
        failed += 1
        bad.append(email)
    if i < len(OWNERS):
        time.sleep(20)

send("info@hillbooker.com", f"[Done] Deepavali owner emails (batch 2): {sent} sent, {failed} failed",
     ("Failed addresses:\n" + "\n".join(bad) + "\n\n" if bad else "")
     + "This is what each owner received:\n\n" + BODY.format(property="Sample Homestay", city="Munnar"))
print(f"DONE: {sent} sent, {failed} failed", flush=True)
